import java.util.*;

class Solution {
    public List<Integer> findWordsContaining(String[] words, char x) {
        List<Integer> indices = new ArrayList<>();
        for (int i = 0; i < words.length; i++) {
            if (words[i].indexOf(x) != -1) {
                indices.add(i);
            }
        }
        return indices;
    }
}

import java.util.*;

class Solution {
    public List<Integer> findWordsContaining(String[] words, char x) {
        List<Integer> indices = new ArrayList<>();
        for (int i = 0; i < words.length; i++) {
            if (contains(words[i], x)) {
                indices.add(i);
            }
        }
        return indices;
    }

    private boolean contains(String word, char x) {
        for (int j = 0; j < word.length(); j++) {
            if (word.charAt(j) == x) {
                return true;
            }
        }
        return false;
    }
}

import java.util.*;

class Solution {
    public List<Integer> findWordsContaining(String[] words, char x) {
        List<Integer> indices = new ArrayList<>();
        int targetMask = 1 << (x - 'a');
        for (int i = 0; i < words.length; i++) {
            int mask = 0;
            for (int j = 0; j < words[i].length(); j++) {
                mask |= 1 << (words[i].charAt(j) - 'a');
            }
            if ((mask & targetMask) != 0) {
                indices.add(i);
            }
        }
        return indices;
    }
}

